void PUSH(int stack[], int &top, int MAX, int val) {
    if (top >= MAX - 1) {
        printf("Stack Overflow!\n");
        return;
    }
    top = top + 1;
    stack[top] = val;
}

int POP(int stack[], int &top) {
    if (top < 0) {
        printf("Stack Underflow!\n");
        return -1;
    }
    int val = stack[top];
    top = top - 1;
    return val;
}
